using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Teams.Domain;
public sealed class TaskState:Entity<short>{private TaskState(){}private TaskState(short id,string code,string name,bool terminal){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));Id=id;Code=Text(code,40).ToUpperInvariant();Name=Text(name,100);IsTerminal=terminal;IsActive=true;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public bool IsTerminal{get;private set;}public bool IsActive{get;private set;}public static TaskState Create(short id,string code,string name,bool terminal)=>new(id,code,name,terminal);private static string Text(string v,int m){var t=v?.Trim()??string.Empty;return t.Length is >0&&t.Length<=m?t:throw new ArgumentException("Value is invalid.");}}
